from pyvkteamsclient.client.base.client import BaseClient
from pyvkteamsclient.client.decorators import api_version_check
from pyvkteamsclient.tracer import tracer


class FoldersMethods(BaseClient):
    """
    Методы группы 'Папки' из https://im-docs.corp.mail.ru/
    """

    @tracer.start_as_current_span("folders.rapi_folders_create")
    @api_version_check(min_version=107)
    def rapi_folders_create(self, title: str, chats: list) -> dict:
        """
        Создание папки
        Добавляет новую папку с указанным именем и содержимым
        На добавление папки рассылается event folders (см. /bos/fetchEvents)
        Версия содержимого для новой папки равна 0
        :param title: Имя новой папки
        :param chats: Список screenname чатов, которые хотим положить в новую папку
        :param title: Имя новой папки
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/folders/create",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"title": title, "chats": chats},
            },
        )

    @tracer.start_as_current_span("folders.rapi_folders_delete")
    @api_version_check(min_version=107)
    def rapi_folders_delete(self, folder_id: int) -> dict:
        """
        Удаление папки
        Удаляет папку с указанным id
        На удаление папки рассылается event folders (см. /bos/fetchEvents)
        :param folderId: id папки из списка папок
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/folders/delete",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"folderId": folder_id},
            },
        )

    @tracer.start_as_current_span("folders.rapi_folders_rename")
    @api_version_check(min_version=107)
    def rapi_folders_rename(self, folder_id: int, title: str) -> dict:
        """
        Переименование папки
        Переименовывает папку по id
        На это действие рассылается event folders (см. /bos/fetchEvents)
        :param folderId: id папки из списка папок
        :param title: Новое имя папки
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/folders/rename",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"folderId": folder_id, "title": title},
            },
        )

    @tracer.start_as_current_span("folders.rapi_folders_reorder")
    @api_version_check(min_version=107)
    def rapi_folders_reorder(self, new_folder_ids_order: list) -> dict:
        """
        Изменение порядка папок
        Расставляет папки в указанном порядке
        На это действие рассылается event folders (см. /bos/fetchEvents)
        :param newFolderIdsOrder: [uniqueItems: true example: List [ 1, 0, 3, 2 ] integer minItems: 2 maxItems: 10
        minimum: 0]
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/folders/reorder",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"newFolderIdsOrder": new_folder_ids_order},
            },
        )

    @tracer.start_as_current_span("folders.rapi_folders_chats_modify")
    @api_version_check(min_version=107)
    def rapi_folders_chats_modify(self, folder_id: int, add_chats: list = (), del_chats: list = ()) -> dict:
        """
        Изменение содержимого папки
        Добавляет/удаляет чаты в папке
        На изменение папки рассылается event folders содержащий порядковые номера версий содержимого папок
        (см. /bos/fetchEvents)
        В ответе метода содержится новая версия содержимого папки
        Очерёдность ответа на запрос и генерации эвента не гарантирована
        Клиенту следует перед вызовом проверять, какая у него версия содержимого и если в результате вызова версия
        увеличилась на 1 и код возврата 20000, то не запрашивать у сервера содержимое папки а изменения
        выполнить локально
        :param folder_id: id папки из списка папок
        :param addChats: Список screenname чатов, которые хотим добавить в папку
        :param delChats: Список screenname чатов, которые хотим удалить из папки
        :return: тело ответа сервера
        """
        params = {"folderId": folder_id}

        if add_chats:
            params["addChats"] = add_chats
        else:
            params["delChats"] = del_chats

        return self.post(
            "rapi/folders/chatsModify",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": params,
            },
        )

    @tracer.start_as_current_span("folders.rapi_request_folders")
    @api_version_check(min_version=107)
    def rapi_request_folders(self) -> dict:
        """
        Запросить папки
        Просит разослать event folders (см. /bos/fetchEvents)
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/folders/requestFolders",
            headers={"Content-Type": "application/json"},
            json={"aimsid": self.aimsid, "reqId": self.getReqId()},
        )

    @tracer.start_as_current_span("folders.rapi_folders_get_content")
    @api_version_check(min_version=107)
    def rapi_folders_get_content(self, folder_id: int) -> dict:
        """
        Получить содержимое папки
        Возвращает список чатов для папки с указанным id
        Список чатов в папке присылается сервером в том же порядке, в котором клиент их добавлял
        :param folder_id: id папки из списка папок
        :return: тело ответа сервера
        """
        return self.post(
            "rapi/folders/getContent",
            headers={"Content-Type": "application/json"},
            json={
                "aimsid": self.aimsid,
                "reqId": self.getReqId(),
                "params": {"folderId": folder_id},
            },
        )

